def conv_10_b(x,b):
    ch=''
    while x!=0:
        r=x%b
        if r<10:
            c=str(r)
        else:
            c=chr(r+55)
        ch=c+ch
        x=x//b
    return ch
print(conv_10_b(240439,16))

